"""Paginate invoice line items for the billing UI."""


def page_count(total_items: int, page_size: int) -> int:
    """Number of pages needed to show total_items, page_size per page."""
    if page_size <= 0:
        raise ValueError("page_size must be positive")
    return (total_items + page_size - 1) // page_size


def get_page(items: list, page: int, page_size: int) -> list:
    """Return the items on 1-based page `page`."""
    if page < 1:
        raise ValueError("page is 1-based")
    start = (page - 1) * page_size
    end = start + page_size - 1
    return items[start:end]


def invoice_total(lines: list[dict]) -> int:
    """Sum of quantity * unit_cents over all lines, in cents."""
    total = 0
    for line in lines:
        total += line["quantity"] * line["unit_cents"]
    return total

"""Check session tokens issued by the login service."""
import hashlib
import hmac
import time

SESSION_TTL_SECONDS = 3600


def sign(user_id: str, issued_at: int, key: bytes) -> str:
    msg = f"{user_id}:{issued_at}".encode("utf-8")
    return hmac.new(key, msg, hashlib.sha256).hexdigest()


def is_valid(user_id: str, issued_at: int, signature: str, key: bytes, now: int | None = None) -> bool:
    """True when the signature matches and the session has not expired."""
    if now is None:
        now = int(time.time())
    expected = sign(user_id, issued_at, key)
    if signature != expected:
        return False
    return now - issued_at <= SESSION_TTL_SECONDS

import unittest

from billing.pagination import page_count, invoice_total


class BillingTest(unittest.TestCase):
    def test_page_count(self):
        self.assertEqual(page_count(10, 5), 2)
        self.assertEqual(page_count(11, 5), 3)

    def test_total(self):
        self.assertEqual(invoice_total([{"quantity": 2, "unit_cents": 150}]), 300)


if __name__ == "__main__":
    unittest.main()

